public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (playerHand)
		{
			if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 1)
			{
				return ReferenceSingleton<PlayerDiceHandHolder>.Instance.IsAtLeastTwoNonMustUseDice();
			}
			return false;
		}
		if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 0)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.IsAnyNonMustUseDice();
		}
		return false;
	}

public override bool CheckCondition(DiceInstance diceInstance)
	{
		return !diceInstance.ActionFace.BattleAction.BaseBattleActionData.HasMandatoryBattleActionInteractionEnum();
	}

public override void Cast(GameObject source)
	{
		if (diceList.Count == 0)
		{
			for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
			{
				diceList.Add(ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i));
			}
			DefaultCast(goBackToDiceTray: false, source);
		}
		else
		{
			DefaultCast(goBackToDiceTray: true, source);
		}
	}

protected virtual void DefaultCast(bool goBackToDiceTray, GameObject source)
	{
		for (int i = 0; i < diceList.Count; i++)
		{
			DiceInstance diceInstance = diceList[i];
			diceInstance.SetDisableDiscard(value: true);
			if (IsVFXEnabled())
			{
				GetVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance);
			}
			SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance);
		}
		SpawnSecondVFXOnPlayerPosition(3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		secondOmenLogic.ActivateOmen(secondAction, secondActionValue, null, source);
		EndAction(goBackToDiceTray);
		ResetVariables();
	}

public int GetDiceSelectionAmount(ActionFace actionFace)
	{
		if (overrideDiceToSelectAmount)
		{
			return diceToSelectAmount;
		}
		return GetNonOverrideDiceToSelectAmount(actionFace);
	}

public virtual int GetNonOverrideDiceToSelectAmount(ActionFace actionFace)
	{
		return actionFace.ModifiedActionValue;
	}

public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectPurify)
		{
			playerGameObjectReference.value.GetComponent<CorruptionStats>().Purify(actionValue, source);
		}
		else if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectCorrupt)
		{
			Debug.Log(corruptionPurifyModifierEnum);
			playerGameObjectReference.value.GetComponent<CorruptionStats>().Corrupt(actionValue, source, corruptionPurifyModifierEnum);
		}
		else
		{
			battleAction.CastTargetAmount(playerGameObjectReference.value, actionValue, source);
		}
	}

public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		TryEnterNoInteractionState();
		amount = GetPlatinumStarLightShieldModifiedAmount(source, amount);
		DefaultCast(target, amount, source, effectFeedback: true, gainingEffectVFXAndSFX: true);
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		TryEnterChooseActionState();
	}

public virtual void DefaultCast(GameObject target, int amount, GameObject source, bool effectFeedback, bool gainingEffectVFXAndSFX)
	{
		if (incorruptible)
		{
			ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorIncorruptibleLightShieldOmenAction?.Invoke();
		}
		else if (barrier)
		{
			ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorBarrierLightShieldOmenAction?.Invoke();
		}
		if (amount != 0)
		{
			SpawnVFX(GetVFXOwnerPosition(target), 3f);
			target.GetComponent<UnitEffects>().AddEffect(effect, amount, effectFeedback, callEffectsCallbacks: true, source, !disableGainEffectSFX && gainingEffectVFXAndSFX, -1, ignoreHollowSkin);
			if (effectFeedback)
			{
				target.GetComponent<SpriteControl>().OnBlink();
			}
			ReferenceSingleton<MiscOmensHandler>.Instance.WickedsCardOmenAction?.Invoke(source, target);
		}
	}

private int GetPlatinumStarLightShieldModifiedAmount(GameObject source, int amount)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanions(source) && ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance is DiceInstance && ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarOmenAction != null && effect == source.GetComponent<UnitEffects>().EffectsList.LightShieldEffect && amount > EffectsValues.NO_VALUE)
		{
			amount = ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarOmenAction(amount);
		}
		return amount;
	}
